done:   jr done

; add32: the four bytes at DE = those at DE + those at HL, low byte first.
;        The carry out of the top byte is left in the carry flag.
add32:  ld b, 4
        or a                    ; nothing to carry into the lowest byte
ad1:    ld a, (de)
        adc a, (hl)             ; this byte, and the carry from the last
        ld (de), a
        inc de
        inc hl                  ; INC of a pair touches no flag ...
        djnz ad1                ; ... and DJNZ none either
        ret

; sub32: the four bytes at DE = those at DE - those at HL, the same way
sub32:  ld b, 4
        or a                    ; nothing to borrow into the lowest byte
sb1:    ld a, (de)
        sbc a, (hl)             ; this byte, less the borrow from the last
        ld (de), a
        inc de
        inc hl
        djnz sb1
        ret

; put32: the four bytes at HL, printed as eight hexadecimal digits, the top
;        byte first. B = row, C = column; C moves on by 8.
put32:  push hl
        inc hl
        inc hl
        inc hl                  ; the top byte
        ld e, 4
p32:    ld a, (hl)
        call puthex
        dec hl
        dec e
        jr nz, p32
        pop hl
        ret

ctext:  db "C=", 0
a0:     dd $000000FF
b0:     dd $00000001
a1:     dd $0000FFFF
b1:     dd $00000001
a2:     dd $00FFFFFF
b2:     dd $00000001
a3:     dd $FFFFFFFF
b3:     dd $00000001
a4:     dd $12345678
b4:     dd $9ABCDEF0
a5:     dd $7FFFFFFF
b5:     dd $00000001
a6:     dd $00010000
b6:     dd $00000001
a7:     dd $00000000
b7:     dd $00000001
a8:     dd $ACF13568
b8:     dd $9ABCDEF0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
